
<template>
  <v-app>
    <v-layout >

      <v-app-bar color="primary" density="compact" class="v-app-bar-app">
        <template v-slot:prepend>
          <v-app-bar-nav-icon @click="openDrawer"></v-app-bar-nav-icon>
        </template>
        <v-app-bar-title>Model based Form-Generator</v-app-bar-title>
      </v-app-bar>  

      <v-navigation-drawer v-model="drawer" permanent width="300">
        <v-list nav  density="compact" >        
          <v-list-item> 
            <v-list-item-title class="text-subtitle-1 font-weight-regular">
              <v-text-field
                ref="dynamicInput"
                class="v-app-txtfield" 
                v-model="search" 
                placeholder="Search..."
                :clearable="true"
                :density="'compact'" 
                :flat="true"
              />
            </v-list-item-title>
          </v-list-item>
          <v-list-item v-for="item in filteredRoutes" :key="item.name"  @click="goto(item)"> 
            <v-list-item-title class="text-subtitle-1 font-weight-regular">{{ item.meta.text }}</v-list-item-title>
          </v-list-item>
        </v-list>
      </v-navigation-drawer>
        
      <v-main>
        <v-container @click="drawer=false" fluid>     
          <v-responsive class="text-center fill-height" >  
            <router-view/>        
          </v-responsive>
        </v-container>
      </v-main>
    </v-layout>
  </v-app>
</template>

<script setup>
  import { ref, reactive, toRefs, computed, onMounted, onUnmounted } from 'vue'
  import { useRouter  } from 'vue-router';
  const dynamicInput = ref()
  const router = useRouter()
  const routes = router.getRoutes().slice(1)
  const search = ref('')
  const drawer = ref(false)

  const openDrawer = () => {
    drawer.value=!drawer.value
    dynamicInput.value.focus();
  }

  const goto = (item)=> { drawer.value = false; router.push(item.name) }
  const filteredRoutes = computed(()=> routes.filter(({ meta })=> !search.value || meta.text.toLowerCase().includes(search.value.toLowerCase()) ) )
</script>

<style>
  @import './app.css';
  .v-app-bar-app { position: fixed!important; }
  .v-app-txtfield { max-height: 2rem; }
</style>