<template>

  <component :id="id" class="form-base" :is= "isContainer()" v-bind="bindContainer()" >
    
    <!-- DEVELOPER FORMBASE ATTRS<br/>  -->
    <!-- <p class="text-body-2"> {{attrs.id}}</p>  -->
    <!-- <p class="text-body-2"> {{attrs.model}}</p>   -->
    <!-- <p class="text-body-2"> {{attrs.schema}}</p>  -->
  
    <!-- FORM TOP SLOT -> #slot-top-form-base -->
    <slot :name="getFormTopSlot()" v-bind="{ id, attrs }" />
  
    <v-row v-bind="bindRow()" >

      <!-- *************** CENTRAL LOOP OF COMPONENTS ************** -->
      <template class="form-base" v-for="(obj, index) in flatCombinedArraySorted" :key="index">
        <v-col 
          v-if="isNotHidden(obj)" 
          v-bind="bindCols(obj)" 
          v-click-outside= "(event) => onClickOutside(obj, index, event, id)"        
        > 
          <!-- v-intersect= "(entries, observer) => onIntersect(entries, observer, obj)"
          v-touch= "{ left: () => onSwipe('left', obj), right: () => onSwipe('right', obj), up: () => onSwipe('up', obj), down: () => onSwipe('down', obj) }" -->
        
          <!-- TOP TYPE SLOT -> #slot-top-element-form-base-[comp] -->
          <slot :name="getTypeTopSlot(obj)" v-bind="{ obj, index, id, attrs }" />
          <!-- TOP KEY SLOT -> #slot-top-key-form-base-[deep-nested-key-name] -->
          <slot :name="getKeyTopSlot(obj)" v-bind="{ obj, index, id, attrs }" />

          <!-- ITEM TYPE SLOT slot replaces complete item of defined TYPE -> #slot-item-element-form-base-[comp] -->
          <slot :name="getTypeItemSlot(obj)" v-bind="{ obj, index, id, attrs }">
            <!-- ITEM KEY SLOT slot replaces complete item of defined KEY -> #slot-item-key-form-base-[deep-nested-key-name] -->
            <slot :name="getKeyItemSlot(obj)" v-bind="{ obj, index, id, attrs }">
            
              <!-- VIEW/GROUP -->
              <template v-if= "isView(obj) || isGroup(obj)" >  
                <!-- slot-top-view-formbase-address-city             -->
                <slot :name="getViewTopSlot(obj)" v-bind= "{ obj, id, index}"/>
                <!-- slot-item-view-formbase-address-city             -->
                <slot :name="getViewItemSlot(obj)" v-bind= "{ obj, id, index}">                
                  <v-form-base 
                    v-bind= "bindAttrs(obj, index, 0)"
                    :row="bindRow(obj)"
                    :cols="bindCols(obj)"                    
                    :modelValue = "getGroupOrViewValue(obj)" 
                  >          
                  <!-- :schema= "obj.schema.schema" -->
                  <template v-for="(_, name) in slots" #[name]="slotData"><slot :name="name" v-bind= "{ id, obj, index, ...slotData}" /></template>                                  
                </v-form-base>
              </slot>
              <!-- slot-bottom-view-formbase-address-city             -->
              <slot :name="getViewBottomSlot(obj)" v-bind= "{ obj, id, index}"/>           
              </template>
              <!-- END VIEW/GROUP -->

              <!-- ARRAY -->
              <template v-else-if= "isArray(obj)" v-for= "(item, idx) in obj.value" :key= "getKeyForArray(id, obj, item, idx)"  >               
                <!-- slot-top-array-formbase-address-city -->
                <slot :name="getArrayTopSlot(obj)" v-bind= "{ obj, id, index, idx, item}"/>
                <!-- slot-item-array-formbase-address-city -->
                <slot :name="getArrayItemSlot(obj)" v-bind= "{ obj, id, index, idx, item}">                
                  <v-form-base 
                  v-bind= "bindAttrs(obj, index, idx )" 
                  :row="bindRow(obj)"
                  :cols="bindCols(obj)"
                  :modelValue = "item" 
                  >
                  <!-- Based on https://gist.github.com/loilo/73c55ed04917ecf5d682ec70a2a1b8e2 -->
                  <template v-for="(_, name) in slots" #[name]="slotData"><slot :name="name" v-bind= "{ id, obj, index, idx, item, ...slotData}" />
                  </template>                        
                </v-form-base>         
              </slot>
              <!-- slot-bottom-array-formbase-address-city -->
                <slot :name="getArrayBottomSlot(obj)" v-bind= "{ obj, id, index, idx, item}"/>
              </template>
              <!-- END ARRAY -->

              <!-- TREEVIEW -->
              <template v-else-if= "isComponent(obj, 'v-treeview')" >
                <v-treeview v-bind= "bindAttrsOmittedOMS(obj, index)" >                  
                  <template v-for="s in getInjectedScopedSlots(id, obj)" #[s]="slotData" >
                    <slot :name="getKeyInjectSlot(obj, s)" v-bind="{ id, obj, index, model, schema, ...slotData }" />
                  </template>
                </v-treeview>                      
              </template>
              <!-- TREEVIEW END -->
              
              <!-- DATA-TABLE -->
              <template v-else-if= "isComponent(obj, 'v-data-table')" > 
                <v-data-table v-bind= "bindAttrsOmittedOMS(obj, index)" >
                  <template v-for="s in getInjectedScopedSlots(id, obj)" #[s]="slotData" >
                    <slot :name="getKeyInjectSlot(obj, s)" v-bind="{ id, obj, index, model, schema, ...slotData }" />
                  </template>
                </v-data-table>                      
              </template>
              <!-- DATA-TABLE  END -->
              
              <!-- BUTTON -->
              <template v-else-if= "isComponent(obj, 'v-btn')" >
                <v-btn v-bind= "bindAttrsButton(obj, index)">
                  <v-icon v-if="hasIconStart(obj.schema)">{{  obj.schema?.icon?.icon || obj.schema?.icon}}</v-icon>                            
                  {{ obj.schema?.text }}
                  <v-icon v-if="hasIconEnd(obj.schema)">{{ obj.schema?.icon?.icon || obj.schema?.icon }}</v-icon> 
                </v-btn>
              </template>
              
              <!-- BUTTON GROUP/TOGGLE -->
              <template v-else-if= "isComponent(obj, 'v-btn-toggle')" >  
                <v-btn-toggle v-bind= "bindAttrsOmittedOMS(obj, index)"> 
                  <template v-for="(option, idx) in obj.schema.options" :key="idx" >
                   <v-btn v-bind=bindOptions(option) >
                     <v-icon v-if="hasIconStart(option)">{{  option?.icon?.icon || option?.icon}}</v-icon>
                     <span v-text="option.text || option.label" v-html="option.html" />                                     
                     <v-icon v-if="hasIconEnd(option)">{{ option?.icon?.icon || option?.icon }}</v-icon> 
                    </v-btn>
                    </template> 
                  </v-btn-toggle>
              </template>  
              <!-- BUTTON GROUP/TOGGLE END  -->
              
              <!-- ELSE ALL COMPONENTS -->
              <template v-else>
                <component
                  :is= "getComponentFromObj(obj)"            
                  v-bind= "bindAttrsOmittedOMS(obj, index)"
                >    
                  <!-- SLOTS Based on https://gist.github.com/loilo/73c55ed04917ecf5d682ec70a2a1b8e2 -->
                  <!-- inject form-base slots into component slots -  ?? work not always with always #[s]="slotData" " -->
                  <template v-for="s in getInjectedScopedSlots(id, obj)" #[s]="slotData" >
                    <slot :name="getKeyInjectSlot(obj, s)" v-bind="{ id, obj, index, model, schema, ...slotData }" />
                  </template>
                 
                  <!-- EXPANSION-PANEL -->
                  <template v-if= "isComponent(obj, 'v-expansion-panels')" v-for="(option, idx) in obj.schema.options" :key="idx"  >                      
                    <v-expansion-panel v-bind= "option" />                      
                  </template>
                  <!-- EXPANSION-PANEL END -->
                  
                  <!-- RADIO GROUP -->
                  <template v-if= "isComponent(obj, 'v-radio-group')" v-for="(option, idx) in obj.schema.options" :key="idx"  >  
                    <v-radio  v-bind= "bindOptions(option)"  >
                      
                      <template v-slot:label >
                        <v-icon v-if="option?.iconL || option?.icon" v-bind="bindIcon(option)">{{ option?.iconL || option?.icon}}</v-icon>
                        <div v-text="option?.label || option?.text" />
                        <v-icon v-if="option?.iconR" v-bind="bindIcon(option)">{{ option?.iconR }}</v-icon>
                      </template>
                      <!-- <template v-for="s in getInjectedScopedSlots(id, obj)" #[s]="slotData" >
                        <slot :name="getKeyInjectSlot(obj, s)+'-option'" v-bind="{ id, obj, index, model, schema, option, ...slotData }" />
                      </template> -->
                    </v-radio>
                  </template> 
                  <!-- RADIO GROUP END -->
                
                  <!-- TOOLTIP - <v-tooltip activator="parent" location="top" text="Tooltip"></v-tooltip> -->
                  <v-tooltip :attach="attachTooltip" v-bind="bindTooltip(obj)" />
                  
                </component>                 
              </template>
              
            </slot>
          </slot>
          
          <!-- BOTTOM KEY SLOT -> #slot-bottom-key-form-base-[deep-nested-key-name] -->
          <slot :name="getKeyBottomSlot(obj)" v-bind="{ obj, index, id, attrs }" />
          <!-- BOTTOM TYPE SLOT -> #slot-bottom-element-form-base-[comp] -->
          <slot :name="getTypeBottomSlot(obj)" v-bind="{ obj, index, id, attrs }" />
          
        </v-col>  
      </template>
      
    </v-row> 
    
    <!-- // TOOLTIP - DON'T DELETE - NEED FOR DISPLAY tooltip:{ contentClass:'background-blue-css', text:'label', ...}  -->
    <div ref="attachTooltip"/>


    <!-- FORM BOTTOM SLOT -> #slot-bottom-form-base -->
    <slot :name="getFormBottomSlot()" v-bind="{ id, attrs }" />
  </component>
</template>

<script setup>
//#region getCALLEE - DEV MODE  REMOVE ON PROD
const getCallee = () => {
    // get callin g Function in ERROR STACK
    const error = new Error();
    let stact = error.stack?.split('\n')
    console.log('--- CALLEE START---------------------------');
    console.log('CALLEE', stact[2]);
    console.log('CALLEE', stact[3]);
    console.log('CALLEE', stact[4]);
    console.log('CALLEE', stact[5]);
    console.log('CALLEE', stact[6]);
}
//#endregion

defineOptions({ inheritAttrs: true}) // IMPORTANT DON'T CHANGE  

//#region IMPORT
import { ref, reactive, isReactive, toRaw, watch, computed, useSlots, useAttrs, getCurrentInstance, useTemplateRef, onMounted } from 'vue'
import vFormBase from './vFormBase.vue' // nested self reference
//#endregion

//#region use EMIT & ATTRS instead of PROPS
const { emit } = getCurrentInstance();
const attrs = useAttrs(); // id, row, cols, model, schema, _shorthand, _buildSchemaFromModel, _buildModel, @update:modelValue, @...
const slots = useSlots()
// console.error('INIT FORMBASE ID:',attrs.id);
// console.error('INIT SLOTS',slots);
// console.error('INIT ATTRS',attrs);
//#endregion

//#region ATTRS INIT MODEL, SCHEMA, CONFIG 
let config = {  
  // DEFAULT CONFIG
  _shorthand: true,                // allows { name:'text',...} in schema instead of { name:{ el:'v-text-field', label:'name'}, ...}'
  _mergeAliasFromMap:true,         // 'false' ignore alias mapping, needs full named vuetify components 'v-text-field' instead of 'text' 
  _buildSchemaFromModel:false,  //  true create from model a schema trying to guess text/chekcbox/numer from model value 
  _buildModel:true,                //  WARNING: use 'false' on own risk in deep nested Objects (doesn't work properly) 
  _handleNumberKeyAsArrayIndex:true, 
  _useDefaultNullValue:true, // allows defining schema:{ name:{ el:'text', nullValue:'empty'}}
  _useOrder:false,           // add _order to schema to control the display order
  // DEFAULT CONFIG OVERWRITTEN FROM ATTRS.CONFIG
  ...attrs.config 
}  

let schema = attrs.schema || ref({})
let globalSchema = attrs.globalSchema ?? schema

let model = attrs.modelValue ?? attrs.model ?? ref({})
//#endregion

//#region  MODEL & SCHEMA & MAIN ARRAYS OF COMPONENTS 
const flatCombinedArray = ref([])
const flatCombinedArraySorted = computed( () => orderFlatByOrderDirectionAsc(flatCombinedArray.value) )

const updateFlatCombinedArrayFromModel = (model) => { flatCombinedArray.value.forEach((obj) => obj.value = get(model, obj.key, null) )}  
const updateFlatCombinedArrayFromSchema = (schema) => { flatCombinedArray.value.forEach((obj) => obj.schema = get(schema, obj.key, null) )}  

// WATCH FLUSH & MODEL & SCHEMA -> TO UPDATE OBJ.value 
watch( ()=>model, (model) => updateFlatCombinedArrayFromModel(model) , {deep:true})

watch( ()=> schema, (schema)=> updateFlatCombinedArrayFromSchema(schema), {deep:true})
//#endregion

//#region FORM & CONTAINER
const isContainer =  () => {
  // attribute:  <v-form-base 
  //  container="v-sheet"
  //  :container="{el:'v-card',...}"
  //  :container={ el:'v-card', title:'Title', ... }  
  //  :container="'div'"
  //  ...
  // schema:    	{ item:{ el:'group| view | array| list', container:{...}, ... }  
  
  let containerSchema = attrs.hasOwnProperty(componentIsContainer) ? attrs[componentIsContainer] : undefined  

  if (!containerSchema ) return emptyContainerDefault
  let { el } = isPlainObject(containerSchema) ? containerSchema : {el:containerSchema}
  
  return el ?  el : emptyContainerDefault
}

const bindContainer = () => {
  if (!attrs.hasOwnProperty(componentIsContainer) ) return {}
  
  const binder = {
    // onSubmit: event => emit('submit', { model, schema, event } ), // must be before ...isplain...
    ...isPlainObject(attrs['container']) ? attrs['container'] : {},
  }  
  return binder
}
//#endregion
  
//#region ID & BASEID
const defaultId = 'formbase'
const id = attrs.id  ?  attrs.id : defaultId
const baseId = attrs.baseId  ?  attrs.baseId : id
//#endregion

//#region ROW, COLS
// ROW   https://vuetifyjs.com/en/api/v-row/ 
const defaultRow = { align:'start' } // , justify:'space-around',  noGutters:true, align:'end', alignContent:'stretch' }  
const bindRow = (obj) => obj?.schema?.row ?? attrs.row ?? defaultRow ;

// COLS   https://vuetifyjs.com/en/api/v-col/
const defaultCols = { cols:12 } 
const colsAttrsArray = ['cols', 'xs', 'sm', 'md', 'lg', 'xl', 'xxl','align-self', 'offset','offsetXs','offsetSm','offsetMd','offsetLg',,'offsetXl','offsetXxl', 'order','tag']
const bindCols = (obj) => {
  
  let schemaCols = isPlainObject(obj.schema?.cols) ? { ...obj.schema?.cols} : {...obj.schema}
  let attrsCols = isPlainObject(attrs.cols) ? { ...attrs.cols} : {...attrs}

  let pickColsFromSchema = pickWithValue(schemaCols, colsAttrsArray)
  let pickColsFromAttribute = pickWithValue(attrsCols, colsAttrsArray)

  return { 
    ...defaultCols, 
    ...pickColsFromAttribute, 
    ...pickColsFromSchema, 
    class:getClassName(obj)
  }

}
//#endregion

//#region ORDER
// Display Order of Elements - by default use 'order' of props in schema 
const orderProperty = '_order'; // don't use orderProperty='order' it has collision with vuetify grid order, and 'order' doesn't work properly!   
const orderDirectionAsc = true;   // 
const orderDistanz = 1000  // start order with 1000
const orderStep = 10      //  add orderStep to ordereIndex on each element iteration
const orderOffset = attrs[orderProperty] + orderDistanz || orderDistanz  // for each recursive frombase call add orderDistanz with 1000 
let orderIndex = orderOffset
const orderKey='schema'
const orderAsc = (a, b) =>  a[orderKey][orderProperty]- b[orderKey][orderProperty]
const orderDesc = (a, b) => b[orderKey][orderProperty] - a[orderKey][orderProperty]
const orderFlatByOrderDirectionAsc  = (array) =>  orderDirectionAsc ? array.sort(orderAsc) : array.sort(orderDesc);
//#endregion

//#region CONST
// const hasSchema = (obj, test) =>  obj.schema[test]
  // const getRowGroupOrArray = (obj) => obj.schema.row || row || defaultRow;
  // const getColGroupOrArray = (obj) => obj.schema.cols || cols || defaultCols;
  // const setItem = (item) => isString(item) ? { item } : item;
  
  const defaultSchemaIfUndefined = key => ({ [componentKey]:'text', placeholder: key, label:key })
  const defaultSchemaIfValueIsString = key => ({ [componentKey]:'text', placeholder: key, label:key })
  const defaultSchemaIfValueIsNumber = key => ({ [componentKey]:'number', placeholder: key, label:key })
  const defaultSchemaIfValueIsBoolean = key => ({ [componentKey]:'checkbox', label:key })
  const defaultSchemaIfValueIsArray = (key, items) => ({ [componentKey]:'select', placeholder: key, label:key, items })
  
  const zeroWidthSpace = String.fromCharCode(0x200B)      //Zero-width Space (U+200B)
  const zeroWidthNonJoiner = String.fromCharCode(0x200C)  //Zero-width non-joiner (U+200C)
  const defaultNullValue = null
  
  const htmlTagsObject = {  
  "<h1>": true, "<h2>": true, "<h3>": true, "<h4>": true, "<h5>": true, "<h6>": true,
  "<p>": true,
  "<a>": true,
  "<span>": true,
  "<br>": true,
  "<hr>": true,
  "<pre>": true,
  "<blockquote>": true,
  "<q>": true,
  "<em>": true,
  "<strong>": true,
  "<code>": true,
  "<sub>": true,
  "<sup>": true,
  "<u>": true,
  "<b>": true,
  "<i>": true,
  "<mark>": true,
  "<small>": true,
  "<del>": true,
  "<ins>": true,
  "<ul>": true,
  "<ol>": true,
  "<li>": true,
  "<dl>": true,
  "<dt>": true,
  "<dd>": true,
  "<img>": true,
  "<audio>": true,
  "<video>": true,
  "<source>": true,
  "<track>": true,
  "<picture>": true,
  "<map>": true,
  "<area>": true,
  "<embed>": true,
  "<object>": true,
  "<article>": true,
  "<aside>": true,
  "<details>": true,
  "<figcaption>": true,
  "<figure>": true,
  "<footer>": true,
  "<header>": true,
  "<main>": true,
  "<nav>": true,
  "<section>": true,
  "<summary>": true,
  "<time>": true,
  "<div>": true,
  "<iframe>": true,
  "<canvas>": true,
  "<svg>": true,
  "<template>": true
  };

  const defaultComponent='default'
  const componentKey = 'el'
  const componentNullValue = 'nullValue'
  const componentClickOutside = 'clickOutside'
  
  const componentIsContainer = 'container'
  const emptyContainerDefault = 'div'
  const componentIsView = 'v-view'
  const componentIsGroup = 'v-group'
  const componentIsArray = 'v-array'
  const componentIsList = 'v-list'
  const componentIsTreeview = 'v-treeview'
  const componentIsDataTable = 'v-datatable'
  
  
  const pathDelimiter = '.';
  const classDelimiter = '-';
  const eventDelimiter = ':';
  
  // SLOT CONST
  const slotAppendix = 'slot';
  const topAppendix = 'top';
  const bottomAppendix = 'bottom';
  const tooltipAppendix = 'tooltip';
  const fileUploadTipAppendix = 'file-upload-tip';
  const fileUploadAppendix = 'file-upload';
  const injectAppendix = 'inject';
  const itemClassAppendix = 'item'; // class obsolet
  const typeClassAppendix = 'element';
  const componentClassAppendix = 'el';
  const keyClassAppendix = 'key';
  const arrayClassAppendix = 'array';
  const viewClassAppendix = 'view';  // is GROUP & VIEW 
  const propertyClassAppendix = 'prop';

  // const arraySlotAppendix = `${slotAppendix}${classDelimiter}${arrayClassAppendix}`;
  // const viewSlotAppendix = `${slotAppendix}${classDelimiter}${arrayViewAppendix}`;
  const injectSlotAppendix = `${slotAppendix}${classDelimiter}${injectAppendix}`;  // slot-inject
  const topSlotAppendix = `${slotAppendix}${classDelimiter}${topAppendix}`;
  const itemSlotAppendix = `${slotAppendix}${classDelimiter}${itemClassAppendix}`;
  const bottomSlotAppendix = `${slotAppendix}${classDelimiter}${bottomAppendix}`;
  const tooltipSlotAppendix = `${slotAppendix}${classDelimiter}${tooltipAppendix}`
  const fileUploadTipSlotAppendix = `${slotAppendix}${classDelimiter}${fileUploadTipAppendix}`
  const fileUploadSlotAppendix = `${slotAppendix}${classDelimiter}${fileUploadAppendix}`

  // hook in Proxy set/get Value  - value or Function
  // const hookGet = 'getVal' // schema.getVal = val or fn(val, obj) => val
  // const hookSet = 'setVal' // schema.setVal = val or fn(val, obj) => val
//#endregion

//#region FNs (es-toolkit/lodash)  
const getComponentFromObj = ({schema}) => schema?.[componentKey]

const isNotHidden = (obj) => !obj.schema.hidden === true

const pick = (obj, keys) => {
  const result = {};  
  for (const key of keys) result[key] = obj[key];
  return result;
}
const pickWithValue = (obj, keys) => {
  const result = {};  
  // take prop only if not undefined
  for (const key of keys) if(obj[key] !== undefined ) {result[key] = obj[key]; } ;
  return result;
}
const omitObject = (obj, keys) => {
  const result = { ...obj };
  for (const key of keys) delete result[key];
  // console.log('Omit Delete Keys ',  keys, result);
  return result
}
const isPlainObject = (value) => {
  if (typeof value !== 'object' || value === null) return false;    
  const proto = Object.getPrototypeOf(value);
  return proto === null || proto === Object.prototype;
}
  
const isEmpty = obj => [Object, Array].includes((obj || {}).constructor) && !Object.entries((obj || {})).length;
const isFunction = (fn) => typeof fn === "function";
const isNumber = (num) => Number.isInteger(num);
const isString = (str) => (str != null && typeof str.valueOf() === "string") ?  true : false
const isEmptyString = (str) => ( str === undefined || str === null || (typeof str === 'string' && str?.trim()==='' ))  ?  true : false

// ############################## SET GET PATH ##############################
const get = (object, path, defaultValue) => path.split(pathDelimiter).reduce((o, p) => o ? o[p] : defaultValue, object)
// create on fly with key 0/1/2  object instead of array
// create on fly with key 0/1/2  array but untested
const set = (object, path, value) => {
  let splitArray = path.split(pathDelimiter)
  if (config?._handleNumericKeyAsArray) {
    // if key is numeric assume this key is part of array!
    const isNumericKey = (i) => isNumber(parseInt(splitArray[i], 10 ))   
    return splitArray.reduce((o,p,i) => o[p] = splitArray.length === ++i ? value : o[p] || (isNumericKey(i) ? [] :{}), object)
  } 
  return splitArray.reduce((o,p,i) => o[p] = splitArray.length === ++i ? value : o[p] || {}, object)
}

const pickedAttrs = (obj, toPickArray) =>pick(bindAttrs(obj),toPickArray)
const omittedAttrs = (obj, index, arrayOfItemsToOmit) => omitObject(bindAttrs(obj, index ), arrayOfItemsToOmit)
const bindAttrsOmittedOMS = (obj, index) => omittedAttrs(obj, index, [ 'obj', 'schema','model','globalSchema'])    
const bindAttrsButton = (obj, index) => omittedAttrs(obj, index, [ 'icon', 'obj', 'schema','model','globalSchema'])    

//#endregion

//#region CLICK OUTSIDE
const onClickOutside = (obj, index, event, id) => {
  let hasClickOutside = obj.schema[componentClickOutside] 
  if (hasClickOutside && isFunction(hasClickOutside)) hasClickOutside(obj.value, event, obj, index, id)
}
//#endregion

//#region METHODS
const isComponent = (obj, component) => obj.schema[componentKey] === component

const isGroup = ({schema}) => schema[componentKey] === componentIsGroup
const isView = ({schema}) => schema[componentKey] === componentIsView 
const isArray = ({schema}) => schema[componentKey] === componentIsArray 
const isList = ({schema}) => schema[componentKey] === componentIsList 

const getGroupOrViewValue = (obj) => (isView(obj)) ? model : get(model,obj.key)    

const bindOptions = (o) =>{
  // schema.options in RADIO/BUTTON 
  o =  isString(o) ? { value: o, label: o } : o
  o.label = o.label || o.text
  return o
}
// extract icon {} from schema.options in BUTTON TOGGLE 
const bindIcon = ({icon}) => isString(icon) ? { icon } : icon  
// exist schema|options.end|.start
const hasIconStart = ( s ) => s.icon?.end ? false : s.icon ? true :false
const hasIconEnd = ( s ) => s.icon?.start ? false : s.icon?.end ? true : false


const constructIdWithIndex = (obj, arrayIndex) => {
  let tmpID = ''
  if (isView(obj) ) {
    tmpID = `${id}`
  } else if (isGroup(obj) ) {   
    tmpID = `${id}-${obj.key}`
  } else if(arrayIndex !== undefined){
    tmpID = `${id}-${obj.key}-${arrayIndex}`
  } else {
    tmpID = `${id}-${obj.key}`
  }
  // console.log('LOG ID constructIdWithIndex', ret,'arrayIndex', arrayIndex, '  id:', id, ' obj.key:', obj?.key);
  return tmpID.replaceAll(pathDelimiter,classDelimiter)
}

const getPathFromID = (attrsNew) => {
    //  BASEID: formbase-develop  ID: formbase-develop.deep.text1 => PATH: deep.text1
    let path = attrsNew.id.replace(`${baseId}${classDelimiter}`,'')
    return path.replaceAll(classDelimiter, pathDelimiter)
}

const constructIndexArray = (id) => id?.match(/-\d+/g)?.map( (val)=> Math.abs(val) )

const deCapitalize = (str) => str.charAt(0).toLowerCase() + str.slice(1)
const capitalize = (str) => str.charAt(0).toUpperCase() + str.slice(1)

const convertClassToCamelCase = (str='') => str.split('-').map((word, index) => index === 0 ? word : word.charAt(0).toUpperCase() + word.slice(1)).join('');
const convertCamelCaseToClass = (str) => str?.replaceAll(/((?<!-)[A-Z])/g, '-$&')?.toLowerCase()

// ---  EVENTS & ATTRS MANAGEMENT --- 
const getEventsArrayStartWithOnAndIsFunc = (obj) => Object.keys(obj).filter(key => key.startsWith('on') && key!==('onUpdate:modelValue') && isFunction(obj[key]));
// const getEventsArrayStartWithOnAndIsFunc = (obj) => Object.keys(obj).filter(key => key.startsWith('on') && isFunction(obj[key]));

const insertColonAndLowercaseSecondCapital = (str) => {
  return str.replace(/([A-Z][^A-Z]*)([A-Z])/, (match, firstPart, secondCap) => {
    return `${firstPart}:${secondCap.toLowerCase()}`;
  });
}

const removeColonAndCapitalizeNextChar = (str) => str.replace(/:(\w)/g, (_, nextChar) => nextChar.toUpperCase());

const sanitizeInlineFunctionNameInSchema= ({schema}) => {
  // sanitze all Inline Function in obj.schema
  // onClickAppendInner -> onClick:appendInner   
  const newSchema=reactive({})
  Object.keys(schema).forEach( (key) => {
    if( key.startsWith('on') && isFunction(schema[key]) ) {
      const newKey = insertColonAndLowercaseSecondCapital(key)       
      newSchema[newKey] = schema[key];
    } else {
      newSchema[key] = schema[key]
    }
  })
  return newSchema
}

