//#region CREATE ATTRS-NEW & ADD, HANDLE EVENTS
const tryNullValue = (schema, value, defaultNullVal = defaultNullValue ) => {
  // IF config._useDefaultNullValue IS TRUE TRY TO SET NULLVALUE IF AVAILABLE { el:'checkbox', nullValue:true }
  return (config?._useDefaultNullValue && schema[componentNullValue] !== undefined && isEmptyString(value)) 
  ? schema[componentNullValue] 
  : value ?? defaultNullVal
} 

const updateValue = (attrsElement, newValue ) => {
  // set last value und update obj

  attrsElement.modelValueLast = attrsElement.modelValue  

  const NullVal = tryNullValue(attrsElement.obj.schema,  newValue, defaultNullValue)
  if(attrsElement.obj.value !== NullVal || attrsElement.obj.value !== attrsElement.obj.schema[componentNullValue] ){
      attrsElement.modelValue = NullVal
  } else {
    // NULLVALUE-HACK adding zeroWidthSpace/zeroWidthNonJoiner avoid error in v-text-field 
    // WARNING DOESN'T WORK TO SELECT DEFINED 'NULLVALUE' IN TEXTFIELD AN THEN KEY 'DELETE'
    // i.e set schema:{ el:'text', nullvalue = 'ABC', ...}  -> select 'ABC'  and press delete -> error in vuetify textfield?!!?
    attrsElement.modelValue = NullVal + zeroWidthNonJoiner  
  }
  
  // attrsElement.modelValue = newValue  
  // attrsElement.obj.value = attrsElement.modelValue  
}

const setNewValue = (attrsElement ) => {
// SET LAST VALUE 
attrsElement.modelValueLast = attrsElement.obj.value

// CHECK NULLVALUE 
// WARNING DOESN'T WORK ONLY!!! WITH SELECT 'NULLVALUE' IN TEXTFIELD AN THEN KEY 'DELETE'
// i.e set nullvalue = 'ABC'    -> select 'ABC'  and press delete -> loose listener?!!?
  
  // attrsElement.obj.value = attrsElement.modelValue
  set( attrsElement.model, attrsElement.path, attrsElement.modelValue )  
}

const createEventSignature = (observer='', attrsElement) =>{
  // create event emitter & listener
  let observerArr = observer.split(eventDelimiter)
  
  // console.warn('LOG OBSERVER: ', observer, ' | ARRAY:', observerArr);
  // LISTENER  onClick, onClick:prepend-inner, onFocus, ...
  let listener = observer
  let emitter = convertCamelCaseToClass(deCapitalize(listener.substring(2)))  
  let matcher = eventDelimiter + convertClassToCamelCase(attrsElement?.id)
  
  // console.log('LOG OBSERVER LISTENER 0: ', listener);
  // console.log('LOG OBSERVER MATCHER0: ', matcher);
  let hasElementDefinition =observer.endsWith(matcher) ? true : false
  
  if (hasElementDefinition) {
    listener = observer.replaceAll(matcher,'')    
    let elementDefinition = observerArr[observerArr.length-1]
    emitter = convertCamelCaseToClass(deCapitalize(listener.substring(2)))+ eventDelimiter + elementDefinition
  } else {
    // listener = observer
    // emitter = convertCamelCaseToClass(deCapitalize(listener.substring(2)))
  }  

  // console.log('LOG OBSERVER LISTENER: ', listener);
  // console.log('LOG OBSERVER EMITTER: ', emitter, 'matchelement', hasElementDefinition );
  // console.log('LOG OBSERVER ATTRS: ', attrsNew );
  
  return { listener, emitter, matcher, hasElementDefinition }
} 

const handleEventModelValue = (modelValue, attrsElement, listener, emitter ) =>{
  // handle 'update:modelValue' Events
  
  // if (!attrsElement._is_update_modelValue_event) {
  // if (!attrsElement._isModelValueEvent) {
  if (attrsElement._isModelValueEvent !== true) {
    
    // COMPLETE ATTRSNEW with additional information
    attrsElement.timestamp = Date.now()
    attrsElement._isCustomEvent = true,
    attrsElement._isModelValueEvent = true,
    attrsElement.listener = listener
    attrsElement.emitter = emitter 
    
    // IMPORTANT  
    updateValue(attrsElement, modelValue  )

    // CHECK FOR INLINE FN
    const InlineFunction = attrsElement?.obj?.schema?.[removeColonAndCapitalizeNextChar(listener)]    
    const hasInlineFunction = isFunction(InlineFunction)    
    attrsElement.hasInlineFunction = hasInlineFunction
    
    if(hasInlineFunction) {
      // CALL INLINE FUNCTION
      let modelValueInline = InlineFunction(attrsElement.modelValue, attrsElement)
      //  console.log('EVENT ### EMIT MODELVALUE INLINE FN ####### ', emitter, modelValueInline, attrsNew.obj.schema.el)        
      // IF FN HAS RETURN VALUE MODIFY MODEL VALUE
      if (modelValueInline !== undefined) {              
        // UPDATE MODEL  
        // attrsElement.modelValue = modelValueInline
        updateValue(attrsElement, modelValueInline )
      }
    }
    
    
    // console.log('EVENT ### EMIT MODELVALUE 1 ####### ', emitter, listener, attrsElement.path, attrsElement.modelValue)        
    
    // Emit model.value
    emit(emitter, attrsElement.modelValue)
    
    // SKIP SET if GROUP/view/ARRAY
    if ( isGroup(attrsElement.obj) ) return; 
    if ( isView(attrsElement.obj) ) return;
    if ( isArray(attrsElement.obj) ) return; 
    if ( isList(attrsElement.obj) ) return;
    
    // console.log('EVENT ### EMIT MODELVALUE 1 PRE SET ####### ModelValue', attrsElement.modelValue, attrsElement)
   
    // set must stay below of group/array/view or list    
    setNewValue(attrsElement )
    

    //  CREATE EMITTER FOR UPDATE:CUSTOM-EVENT
    if (!attrsElement[`onUpdate:customEvent`]) return
    
    const idCamelCased = convertClassToCamelCase(attrsElement.id)
    const addElementNameIfEventExists =  attrsElement[`onUpdate:customEvent:${idCamelCased}`] ? `:${idCamelCased}` : ``
    attrsElement.emitter = 'update:customEvent' + addElementNameIfEventExists    
    // console.log('EVENT ### EMIT CUSTOMEVENT 2 AFTER SET ####### ', attrsElement.emitter)        
    emit(attrsElement.emitter, attrsElement)

  } else {
    // console.log('EVENT ### EMIT EV 1 #### ', emitter, attrsElement);
    emit(emitter, modelValue)    
  }
}

const handleEvent = (event, attrsElement, listener, emitter) => {

  //  console.log('LOG handleEventModelValue INTRO ', attrsNew);  
  // if (!event._isCustomEvent ) {
  if (event._isCustomEvent !== true) {
    // COMPLETE ATTRSNEW with additional information
    attrsElement.timestamp = Date.now()
    attrsElement._isCustomEvent = true
    attrsElement._isModelValueEvent = false
    attrsElement.listener = listener
    attrsElement.emitter = emitter 
    attrsElement.event = event
    
    // CHECK FOR INLINE FN - adapt original inline listener with '_' from schema
    const InlineFunction = attrsElement?.obj?.schema?.[removeColonAndCapitalizeNextChar(listener)]
    const hasInlineFunction = isFunction(InlineFunction)
    attrsElement.hasInlineFunction = hasInlineFunction    
    
    // console.log('EVENT ### EMIT ATRRS PRE INLINE FNB #### ', emitter, attrsElement);
    if(hasInlineFunction) {
      // console.log('EVENT INLINE ### EMIT ATRRS PRE INLINE FNB #### ', emitter, attrsElement);
      // CALL INLINE FUNCTION
      let modelValueInline = InlineFunction(attrsElement.modelValue, attrsElement)
      // IMPORTANT: InlineFunction - RETURN VALUE will modify modelValue
      if (modelValueInline !== undefined) {              
        attrsElement.modelValue = modelValueInline
        // UPDATE MODEL  
        setNewValue(attrsElement);
      }
    }     
    
    // console.log('EVENT ### EMIT ATRRS AFTER #### ', emitter, attrsElement);
    emit(emitter, attrsElement)    
    if(event?.stopPropagation) event?.stopPropagation()          

  } else {
    // console.log('EVENT ### EMIT EVENT WITH CUSTOMEVENT #### ', emitter, attrsElement);
    // BYPASS EVENTS IF ALREADY A CUSTOMEVENT
    emit(emitter, event)
  }

}

const addHandlerToEvents = (attrsElement) => {

  let observerArray= getEventsArrayStartWithOnAndIsFunc(attrsElement)
  
  // Add 'onUpdate:modelValue' necessary to bubble values through nested formbase 
  observerArray.unshift('onUpdate:modelValue')
  // vs
  // observerArray.push('onUpdate:modelValue')
  // observerArray =observerArray.reverse()  
  
  // observerArray.push('onUpdate:search')
  // observerArray.push('onUpdate:focused')
  
  // Reverse ORDER is relevant in formbase-component as Attribut : 'onClick:formbase-....' ->  'onClick'
  // <v-form-base
  //   :model= "myModel"
  //   :schema= "mySchema"             
  //   @click:formbase-text="log"
  //   @click="log"  // last event finally catch all 
  // />
      
  // console.warn('log# generateEvents  --------- ATTRS_NEW ---'+ attrsNew.id +'---------------------------');
  // console.log('log# generateEvents attrsNew:', attrsNew );            
  // console.log('log# generateEvents observerArr ',observerArray);

  observerArray.forEach( observer => {
  
    const { listener, emitter } = createEventSignature(observer, attrsElement)
    
    const path = getPathFromID(attrsElement)      
    attrsElement.path=path
        
    // console.warn('EVENT ### EVENT #######      Observe:', observer)
    // console.warn('EVENT ### PRE EVENT #######      attrsElement:', attrsElement)
    // console.log('EVENT ### EVENT ####### Attrs.ID:', attrsNew.id, '| ID:', id);
    // console.log('EVENT ### EVENT #######  Listen:', listener,' | Emitter:', emitter);
    
    
    if (listener.startsWith('onUpdate') ) {
      // ADD NEW UPDATE EVENT 
      // console.log('EVENT ### EVENT ####### HANDLE-EVENT-MODEL-UPDATE:----------------', listener, emitter)
      attrsElement[listener]= $event => handleEventModelValue($event, attrsElement, listener, emitter, path)          
    } else {
      // ADD NEW EVENT 
      // console.log('EVENT ### EVENT ####### HANDLE-EVENT:----------', listener, emitter)
      attrsElement[listener]= $event => handleEvent($event, attrsElement, listener, emitter, path)
    }
    
  })

  return attrsElement
} 

