  const id = constructIdWithIndex( obj, arrayIndex)
  const indexOfArrays = constructIndexArray( id )    
  const modelValue = obj.value
    
  let attrsElement = { 
    // ------------------ PROPS - ORDER IS RELEVANT -----------------------------------
    ...attrs,             // all attributes from calling COMPONENT
    ...schema,   // // extraxt schema from obj and merge sanitized props
    id,    
