    // ['onClick:formbaseTasks1Task0DoneX1Test']: $event => handleEvent($event, attrsNew, 'click:formbaseTasks1Task0DoneX1Test'),
    // ['onClick:formbaseTasks1Task0DoneX1Test']: $event => handleEvent($event, attrsNew, 'click:formbaseTasks1Task0DoneX1Test'),
    // ['onClick:formbaseTasks1Task0DoneX1Test']: $event => handleEvent($event, attrsNew, 'click:formbase-tasks-1-task-0-doneX1Test'),
    // ['onClick:formbase-tasks-0-doneX1Test']: $event => handleEvent($event, attrsNew, 'click:formbase-tasks-0-doneX1Test'),
    // ['onClick:formbase-tasks-0-done1']: $event => handleEvent($event, attrsNew, 'click:formbaseTasks0Done1'),
   
  // console.log('EVENTS NOW ADDED PRE ', attrsNew);  
