const attachTooltip = useTemplateRef('attachTooltip')

const bindTooltip = ( {schema, value=''} ) => {
  let tooltipValid = schema?.tooltip ?? attrs.tooltip
  if (!tooltipValid) return null
  
  let text=isPlainObject(tooltipValid) ? tooltipValid?.text : isString(tooltipValid) ? tooltipValid : '@label'  
  
  if (text === '@value') {
    text = value.toString() || schema?.label || schema?.hint; 
  } else if (text === '@label') {
    text =schema?.label; 
  } else if (text === '@text') {
    text =schema?.text; 
  } else if (text === '@hint') {
    text =schema?.hint; 
  } else if (text === '@content' || isEmptyString(text)) {
    text =schema?.text || schema?.label || schema?.hint; 
  }

  tooltipValid = isPlainObject(tooltipValid) ? tooltipValid : { text }  
  // console.log({ location:'bottom', activator:'parent', ...tooltipValid, text })
  return { location:'bottom', activator:'parent', ...tooltipValid, text }
}
