const getFileUploadSlot = (obj) => {
  // Slot for Top Line in Formbase -> 'slot-formbase-top'
  return `${fileUploadSlotAppendix}`;
}
//
// TYPE SLOTS
const getTypeTopSlot = (obj) => {
  // get Type specific slot name  -> 'slot-top-element-radio'
  return getTypeClassNameWithAppendix(obj,`${topSlotAppendix}-${typeClassAppendix}`);
}
const getTypeItemSlot = (obj) => {
  // get Type specific slot name  -> 'slot-item-element--radio'
  return getTypeClassNameWithAppendix(obj, `${itemSlotAppendix}-${typeClassAppendix}`);
}
const getTypeBottomSlot = (obj) => {
  // get Type specific slot name  -> 'slot-bottom-element--radio'
  return getTypeClassNameWithAppendix(obj, `${bottomSlotAppendix}-${typeClassAppendix}`);
}
//#endregion

//#region CLASS Names
const getPropertyClassNameWithAppendix = (obj, appendix) => {
  // get PROP specific name by app-/prepending 'appendix-' and replacing '.' with '-' in nested key path  -> 'controls switch'
   return obj.key
    ? obj.key
        .split(pathDelimiter)
        .map((s) => `${appendix ? appendix + classDelimiter : ''}${s}`)
        .join(' ')
    : '';    
  }
const getPropertyClassName = (obj) => {
  return getPropertyClassNameWithAppendix(obj, propertyClassAppendix);
}
const getKeyID = (obj) => {
  // get KEY specific name by app-/prepending 'appendix-' and replacing '.' with '-' in nested key path  -> 'top-slot-address-city'  
  return `${id ? id + classDelimiter : ''}${obj.key}`;
}
const getBaseIDClassName = () => baseId !== id ? baseId: ``

const getKeyClassNameWithAppendix = (obj, appendix) => {
  // get KEY specific name by app-/prepending 'appendix-' and replacing '.' with '-' in nested key path  -> 'top-slot-address-city'  
  return `${appendix ? appendix + classDelimiter : ''}${id ? id + classDelimiter : ''}${obj.key}`;
}
const getKeyClassName = (obj) =>{
  return getKeyClassNameWithAppendix(obj, keyClassAppendix);
}
const getTypeClassNameWithAppendix = (obj, appendix) => {
  // get use Formbase ID for spec  TYPE specific class name by prepending '-type' -> 'type-checkbox'
  return `${appendix ? appendix + classDelimiter : ''}${
    id ? id + classDelimiter : ''
  }${obj.schema[componentKey]}`;
}
const getTypeClassName = (obj) =>{
  return getTypeClassNameWithAppendix(obj, typeClassAppendix);
}
const getComponentClassNameWithAppendix = (obj, appendix) => {
  // ident to TYPE but without ID specific class name by prepending 'el' -> 'el-checkbox'
  return `${appendix ? appendix + classDelimiter : ''}${
    obj.schema[componentKey]
  }`;
}
const getComponentClassName = (obj) =>{
  return getComponentClassNameWithAppendix(obj, componentClassAppendix);
}
const getClassName = (obj) =>{
  // combines all class definitions into a single classname
  // class => ie. 'form-base item type-checkbox key-address-zip prop-adress prop-zip'
  let finalclass =`${id} ${getBaseIDClassName()} ${getTypeClassName(obj)} ${getKeyClassName(obj)} ${getComponentClassName(obj)} ${getPropertyClassName(obj)}`
  return finalclass.replaceAll(pathDelimiter,'-').toLowerCase();
}

//#endregion


//#region SHORTHAND, NULLVALUE AUTOGENERATE SCHEMA, MERGE MAP    
// hook in Proxy set/get Value  - value or Function
const hookGet = 'getVal' // schema.getVal = val or fn(val, obj) => val
const hookSet = 'setVal' // schema.setVal = val or fn(val, obj) => val

const createProxyForObject = (obj) => {    
    // handle schema[hookSet] and schema[hookGet] to control incomig and outgoing value from component
    return new Proxy(obj, {
      get(target, prop, receiver) {
        const ts = target.schema;
        if (prop === 'value' && ts?.[hookGet]) {
          const tk = target.key;
          const tp = target[prop];
          // console.log('##GET', isFunction(ts[hookGet]), tk, tp, target, modelInt, schema)
          const proxyValue = isFunction(ts[hookGet])
            ? ts[hookGet](tp, target)
            : ts[hookGet]
            ? ts[hookGet]
            : tp;
          return proxyValue;
        }
        return target[prop];
      },
      set(target, prop, val, receiver) {
        const ts = target?.schema
        if (prop === 'value' && ts?.[hookSet]) {
          const tk = target.key;
          const tp = target[prop];
          console.log('##PROXY', target, prop, val, receiver  )
          console.log('##SET', val, tk, tp, target  )
          target[prop] = isFunction(ts[hookSet])
            ? ts[hookSet](val, tp, target )
            : ts[hookSet]
            ? ts[hookSet]
            : tp;
        } else {
          target[prop] = val;
        }
        
        return true;
      },
    });
  }

  const createFlatCombinedArray = (model, schema, currentPath)=>{
    
    // TRY TO BUILD NEW SCHEMA FROM MODEL    
    schema = buildSchema(model, schema);
   
    const paths = []
    
    const walkThroughKeys = (model, schema, currentPath, orderIndex ) => {

      for (const key in schema) {
        if (schema.hasOwnProperty(key)) {   
          const newPath = currentPath ? `${currentPath}${pathDelimiter}${key}` : key;
          
          let keySchema = toRaw(schema[key])

          if (typeof keySchema === 'object' && keySchema !== null && !keySchema.el ) {          
            
            let setValue =  get(model, newPath) 
            if (!setValue && config?._buildModel) set(model, newPath, Array.isArray(keySchema) ? [] :{});
            walkThroughKeys(model, keySchema, newPath, orderIndex); 

          } else {
           
            if (componentIsGroup.endsWith(keySchema?.[componentKey]) || componentIsView.endsWith(keySchema?.[componentKey]) || componentIsArray.endsWith(keySchema?.[componentKey])  )  {
              
              keySchema =  getShorthandSchema(newPath, keySchema);
              keySchema = mergeSchemaWithMappedSchema(keySchema) 
              schema[key] = tryToAddOrderIndex(keySchema) 
              
              // handle container GROUP
              keySchema.container =  getShorthandSchema(newPath, keySchema.container);
              keySchema.container = mergeSchemaWithMappedSchema(keySchema.container) 
              
              const ValueArrObj =Array.isArray(keySchema) ? [] :{}
              
              // get value on current path
              let newValue =  get(model, newPath)
              // set modified new value              
              if (!newValue && config?._buildModel)  set(model, newPath, ValueArrObj);
              // add new obj to array
              // paths.push(({ key:newPath, value:newValue, schema:schema[key] }) ) 
              paths.push( createProxyForObject({ key:newPath, value:newValue, schema:schema[key]}) ); // Add the current path       
            
            } else {
            
              keySchema =  getShorthandSchema(newPath, keySchema);
              keySchema = mergeSchemaWithMappedSchema(keySchema) 
              schema[key] = tryToAddOrderIndex(keySchema)

              // get value on current path
              let newValue = get(model, newPath)              
              // try to set nullValue 
              newValue  = tryNullValue(keySchema, newValue, defaultNullValue)
              // set modified new value
              if(config?._buildModel) set(model, newPath, newValue);
              
              // add new obj to array              
              // paths.push(({ key:newPath, value:newValue, schema:schema[key]}) ); // Add the current path                     
              paths.push( createProxyForObject({ key:newPath, value:newValue, schema:schema[key]}) ); // Add the current path       
              
            }
          }          
        }
      }
    }
    
    walkThroughKeys(model, schema, currentPath, orderIndex)

    return paths
}

const tryToAddOrderIndex= (keySchema ) => {
  // USE GLOBAL VAR/CONST orderIndex & orderStep
  // TO KEEP ORDER OF PROPS IN OBJECT -> IF NO ORDER -> NEW ORDER ADDED TO SCHEMA        
  if( keySchema[orderProperty] === undefined && config?._useOrder===true ) {
    // passing orderOffset = attrs[orderProperty] + orderDistanz 
    // each nested formbase has additional orderOffset
    keySchema[orderProperty]= orderIndex;   
    orderIndex +=orderStep     
  }
  return keySchema
}

const getShorthandSchema = (key, keySchema) => {
  // CONVERT SHORTHAND DEFINITION  
  // IF SCHEMA ELEMENT name: { el:'text'}
  // IF SCHEMA ELEMENT name: 'text' => { el:'text', placeholder: 'name', label:'name'}

  if ( config?._shorthand === true && isString(keySchema)) {
    return mergeSchemaWithMappedSchema({ [componentKey]: keySchema, placeholder: key, label:key })  
  }
  return keySchema
}

const buildSchema = (model, schema) => {
  
  if (!config?._buildSchemaFromModel ) return schema
  
  const path = ''
  const schemaInt = {}

  const walkThroughKeys = (model, schema, currentPath ) => {

    for (const key in model) {
      if (model.hasOwnProperty(key)) { 
          
        const newPath = currentPath ? `${currentPath}${pathDelimiter}${key}` : key
        let keyModel = toRaw(model[key])
        let keySchema = toRaw(schema?.[key])
        
        if (typeof keyModel === 'object'    ) {                    
          set(schemaInt,newPath, { })
          walkThroughKeys(keyModel, keySchema, newPath)
        } else {
          if( !keySchema ) {
            let newBuildSchema = getDefaultSchemaFromModelValue(keyModel, key)
            set(schemaInt, newPath, newBuildSchema)
          } else {
            set(schemaInt, newPath, keySchema)
          }
        }          
      }
    }
  }

  walkThroughKeys(model, schema, path)

  Object.keys(schema).forEach((key) => (delete schema[key]));
  Object.keys(model).forEach((key) => (schema[key] = schemaInt[key]));
  
  console.warn('Info: config._buildSchemaFromModel = true) - new schema was generated, based on model', schema);

  return schema
}

const getDefaultSchemaFromModelValue=(val, key)=>{
  if (typeof val === 'string') return defaultSchemaIfValueIsString(key);
  if (typeof val === 'number') return defaultSchemaIfValueIsNumber(key);
  if (typeof val === 'boolean') return defaultSchemaIfValueIsBoolean(key);
  if (Array.isArray(val) && !isPlainObject(val?.[0]) && !Array.isArray(schema[key]) ) return defaultSchemaIfValueIsArray(key, val);
  return defaultSchemaIfUndefined(key);
}

const getSchemaFromMapToVuetify = (obj) => {    
  
  let {[componentKey]:element} = obj

  if (!element || isEmptyString(element) ) throw 'Undefined element - ' + JSON.stringify(obj)
  
  element = element?.replace(/\s+/g, '')  // remove whitespaces    
  element = convertClassToCamelCase(element)  //  button-group -> buttonGroup (to CAMELCASE)
  
  // if element is key in mapToVuetify exit found -> card:{ el:'v-card', color:'red',...}
  const mappedSchema = mapToVuetify[element]    
  if (mappedSchema) return mappedSchema ;   
  
  // create 'text-field' or 'v-text-field'
  // console.log('getSchemaFromMapToVuetify element',element);
  
  element = convertCamelCaseToClass(element)   //  buttonGroup -> button-group (to CLASS) 
  
  // if { el:'div',...}  is in htmlTagsObject { '<div>':true, ... } exit without adding 'v-')
  if ( htmlTagsObject ['<'+element+'>'] ) return  {[componentKey]: element};
  if ( element.startsWith('v-') ) return  {[componentKey]: element};
  // let e= (htmlTag.includes(element) || element.startsWith('v-')) ? element : `v-${element}` 
  
  // // return { el:'v-text-field' }  
  
  return {[componentKey]: `v-${element}`}  
}

const mergeSchemaWithMappedSchema = (keySchema) => {
  // IF config._mergeAliasFromMap IS TRUE TRY TO LOOKUP mapToVuetify AND MERGE ALIAS SCHEMA 
  // if ( !keySchema?.[componentKey] || !config?._mergeAliasFromMap ) return schema
  if ( !keySchema || !config?._mergeAliasFromMap ) return keySchema

  const mapSchema = getSchemaFromMapToVuetify(keySchema) 
  keySchema =  ({...mapSchema, ...keySchema })
  if(mapSchema[componentKey]) keySchema[componentKey] = mapSchema[componentKey];
  return keySchema
}
//#endregion

//#region REBUILD ARRAYS - MAIN FN
  const buildArrays = (model, schema) => {
    
    // undefined, null or primitive value for model/schema
    // can't work because you need reference to object for working on
    if ( !isReactive(model) ) {
      throw `Attribute 'model' must be a ref({}) - Try 'const myModel = ref({})' and '<v-form-base :model="myModel" :schema="mySchema" />'`;
    }
    if ( !isReactive(schema) ) {
      throw `Attribute 'schema' must be a ref({}). Try 'const mySchema = ref({})' and '<v-form-base :model="myModel" :schema="mySchema" />'`;
    }
    
    // warn on empty model & schema
    if (isEmpty(schema) && isEmpty(model)) {
      console.warn(`At least one of the properties 'model' or 'schema' in <v-form-base /> must not be empty Object. Ignore this Warning on lazy/async loading 'model' or 'schema' `)
    }  

    // CREATE MAIN ARRAY 'flatCombinedArray' WITH ITEMS [{ key, value, schema }, ... ]
    const flatArray = createFlatCombinedArray(model, schema, '')

    // console.warn('formbase id:', id, '| flatArray:',   flatArray);

    return flatArray

  }  
//#endregion
  
// START HERE ...
onMounted( () => flatCombinedArray.value = buildArrays(model, schema))

</script>
